import{_ as a,o as n,c as s,a3 as e}from"./chunks/framework.bvEHUNtb.js";const u=JSON.parse('{"title":"06 先天八卦","description":"从《说卦传》、邵雍先天学与朱熹图式理解先天八卦。","frontmatter":{"title":"06 先天八卦","description":"从《说卦传》、邵雍先天学与朱熹图式理解先天八卦。","category":"guide","aliases":["先天八卦","伏羲八卦"]},"headers":[],"relativePath":"topics/traditional-wisdom/symbols/xian-tian-ba-gua.md","filePath":"topics/traditional-wisdom/symbols/xian-tian-ba-gua.md","lastUpdated":1786982540000}'),l={name:"topics/traditional-wisdom/symbols/xian-tian-ba-gua.md"};function p(i,t,o,d,c,r){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="_06-·-先天八卦-宇宙的第一张对称图" tabindex="-1">06 · 先天八卦：宇宙的第一张对称图 <a class="header-anchor" href="#_06-·-先天八卦-宇宙的第一张对称图" aria-label="Permalink to &quot;06 · 先天八卦：宇宙的第一张对称图&quot;">​</a></h1><h2 id="版本与引用说明" tabindex="-1">版本与引用说明 <a class="header-anchor" href="#版本与引用说明" aria-label="Permalink to &quot;版本与引用说明&quot;">​</a></h2><p>&quot;先天八卦&quot;这一名称，<strong>不见于先秦文献</strong>。<br> &quot;先天&quot;之名，由北宋邵雍（1011—1077年）正式提出，其图式经朱熹《周易本义》（1177年）定型，成为后世通行标准。</p><p>但先天八卦所依据的核心原文，来自《周易·说卦传》——这是确凿的先秦文献。</p><p>本篇<strong>严格区分</strong>：</p><ul><li>《说卦传》原文（先秦）</li><li>邵雍的&quot;先天学&quot;建构（北宋）</li><li>朱熹的图式定型（南宋）</li></ul><p>三者不混为一谈。</p><hr><h2 id="一、先说位置-它在体系中的哪里" tabindex="-1">一、先说位置：它在体系中的哪里？ <a class="header-anchor" href="#一、先说位置-它在体系中的哪里" aria-label="Permalink to &quot;一、先说位置：它在体系中的哪里？&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>道</span></span>
<span class="line"><span> └─ 阴阳（一分为二）</span></span>
<span class="line"><span>      └─ 四象（二分为四）</span></span>
<span class="line"><span>           └─ 八卦（四分为八）</span></span>
<span class="line"><span>                ├─ 先天八卦（体）← 我们在这里</span></span>
<span class="line"><span>                │    = 八种基本状态的本质关系</span></span>
<span class="line"><span>                │    = 宇宙的对称结构</span></span>
<span class="line"><span>                └─ 后天八卦（用）</span></span>
<span class="line"><span>                     = 八种状态在时空中的流行</span></span></code></pre></div><p>先天八卦回答的问题是：</p><blockquote><p><strong>这八种基本状态，在本质上是什么关系？它们如何构成一个完整的宇宙？</strong></p></blockquote><p>后天八卦回答的问题是：</p><blockquote><p><strong>这八种状态，在时间和空间中如何运行？</strong></p></blockquote><p>先体后用。先搞清楚&quot;是什么&quot;，再谈&quot;怎么动&quot;。</p><hr><h2 id="二、原典依据《说卦传》" tabindex="-1">二、原典依据《说卦传》 <a class="header-anchor" href="#二、原典依据《说卦传》" aria-label="Permalink to &quot;二、原典依据《说卦传》&quot;">​</a></h2><blockquote><p>【原典】《周易·说卦传》第三章，孔子《十翼》之一<br> 【时代】西周至春秋<br> 【原文】<strong>天地定位，山泽通气，雷风相薄，水火不相射，八卦相错，数往者顺，知来者逆，是故易逆数也。</strong></p></blockquote><p>逐句拆解：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;天地定位&quot;</span></span>
<span class="line"><span>  乾（天）与坤（地）确定上下位置。</span></span>
<span class="line"><span>  = 宇宙的第一对坐标轴：上/下，天/地，纯阳/纯阴。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;山泽通气&quot;</span></span>
<span class="line"><span>  艮（山）与兑（泽）气息相通。</span></span>
<span class="line"><span>  = 山高而静，泽低而动；</span></span>
<span class="line"><span>    山中水汽下降，泽中水汽上升，两者循环。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;雷风相薄&quot;</span></span>
<span class="line"><span>  震（雷）与巽（风）相互激荡。</span></span>
<span class="line"><span>  = 雷动风行，互为因果，是同一现象的两面。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;水火不相射&quot;</span></span>
<span class="line"><span>  坎（水）与离（火）互不侵犯。</span></span>
<span class="line"><span>  = &quot;射&quot;，古义为&quot;厌弃、排斥&quot;。</span></span>
<span class="line"><span>    水火相对，各守其位，对立共存。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;八卦相错&quot;</span></span>
<span class="line"><span>  八卦交错排列，形成完整体系。</span></span>
<span class="line"><span>  = 不是八个独立符号的堆砌，</span></span>
<span class="line"><span>    而是一个相互咬合的整体结构。</span></span></code></pre></div><blockquote><p>⚠️ <strong>重要说明</strong>：《说卦传》这段原文，<strong>描述的是八卦的对待关系</strong>，<br> 并没有明确说&quot;这就是先天八卦的方位图&quot;。<br> 将这段文字与具体方位图式对应，是邵雍的诠释工作，不是《说卦传》的原意。<br> ——廖名春《周易经传与易学史新论》，齐鲁书社，2001年</p></blockquote><hr><h2 id="三、-先天-之名从哪里来" tabindex="-1">三、&quot;先天&quot;之名从哪里来？ <a class="header-anchor" href="#三、-先天-之名从哪里来" aria-label="Permalink to &quot;三、&quot;先天&quot;之名从哪里来？&quot;">​</a></h2><blockquote><p>【原典】邵雍《观物外篇》，北宋，约1060年代<br> 【原文】<strong>&quot;先天之学，心也；后天之学，迹也。&quot;</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先天 = 天地未形之前，宇宙的本然状态 = 体，本质，静态对称</span></span>
<span class="line"><span>后天 = 天地既形之后，万物的流行状态 = 用，运动，动态展开</span></span></code></pre></div><blockquote><p>章伟文《先天学与道教丹道之关系考察》（《周易研究》，2014年）指出：<br> 邵雍的&quot;先天学&quot;，深受道教内丹传统影响，陈抟（约871—989年）是其重要思想来源。<br> &quot;先天&quot;概念本身，有道家修炼的背景，不纯粹是儒家易学的产物。</p></blockquote><p>这里有一个值得停下来想的地方：</p><p>&quot;先天之学，心也&quot;——邵雍说先天是&quot;心&quot;的学问。<br> 不是眼睛看到的，不是手可以摸到的，是在一切感官经验之前，就已经存在的那个结构。</p><p>用今天的话说：先天八卦，是宇宙的<strong>底层代码</strong>，不是界面。</p><hr><h2 id="四、先天八卦图-方位与结构" tabindex="-1">四、先天八卦图：方位与结构 <a class="header-anchor" href="#四、先天八卦图-方位与结构" aria-label="Permalink to &quot;四、先天八卦图：方位与结构&quot;">​</a></h2><blockquote><p>📌 <strong>【先天八卦方位图预留位置】</strong><br> 圆形排布：上乾（南）下坤（北），左离（东）右坎（西）</p></blockquote><h3 id="标准方位-上南下北-面南而立" tabindex="-1">标准方位（上南下北，面南而立） <a class="header-anchor" href="#标准方位-上南下北-面南而立" aria-label="Permalink to &quot;标准方位（上南下北，面南而立）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            乾（☰）南·上</span></span>
<span class="line"><span>    兑（☱）东南        巽（☴）西南</span></span>
<span class="line"><span>    离（☲）东                  坎（☵）西</span></span>
<span class="line"><span>    震（☳）东北        艮（☶）西北</span></span>
<span class="line"><span>            坤（☷）北·下</span></span></code></pre></div><blockquote><p>⚠️ 先天八卦是<strong>上南下北</strong>——古代&quot;面南而立&quot;的观察视角。<br> 圣王面南而坐，左手边是东（日出），右手边是西（日落）。<br> 与我们今天地图的上北下南习惯<strong>相反</strong>，初学者务必注意。</p></blockquote><h3 id="四对对待关系" tabindex="-1">四对对待关系 <a class="header-anchor" href="#四对对待关系" aria-label="Permalink to &quot;四对对待关系&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾（☰）↔ 坤（☷）   纯阳 ↔ 纯阴    天 ↔ 地</span></span>
<span class="line"><span>离（☲）↔ 坎（☵）   中阳 ↔ 中阴    火 ↔ 水</span></span>
<span class="line"><span>震（☳）↔ 巽（☴）   长阳 ↔ 长阴    雷 ↔ 风</span></span>
<span class="line"><span>兑（☱）↔ 艮（☶）   少阳 ↔ 少阴    泽 ↔ 山</span></span>
<span class="line"><span></span></span>
<span class="line"><span>规律：每一对，阴阳爻完全互换（互为综卦）。</span></span></code></pre></div><hr><h2 id="五、八卦的生成-从太极到八卦" tabindex="-1">五、八卦的生成：从太极到八卦 <a class="header-anchor" href="#五、八卦的生成-从太极到八卦" aria-label="Permalink to &quot;五、八卦的生成：从太极到八卦&quot;">​</a></h2><blockquote><p>【原典】《周易·系辞上传》第十一章<br> 【原文】<strong>易有太极，是生两仪，两仪生四象，四象生八卦，八卦定吉凶，吉凶生大业。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>太极（一）→ 两仪（阴/阳）→ 四象 → 八卦</span></span></code></pre></div><p>用二进制理解（莱布尼茨1703年发现对应关系）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>坤☷=000  艮☶=001  坎☵=010  巽☴=011</span></span>
<span class="line"><span>震☳=100  离☲=101  兑☱=110  乾☰=111</span></span></code></pre></div><p>先天八卦的排列，正好是二进制0到7的完整序列。</p><blockquote><p><strong>先天八卦的生成逻辑（一分为二，再一分为二），与二进制的底层逻辑完全同构。</strong><br> 现代科技与易理在结构上殊途同归。这说明&quot;二分逻辑&quot;本身，是描述宇宙的一种极为基本的方式。</p><p>莱布尼茨在1703年写信给法国传教士白晋（Joachim Bouvet），<br> 看到先天六十四卦图后大为震惊，认为与他“发明”的二进制完全对应。</p></blockquote><h2 id="六、八卦基本属性表" tabindex="-1">六、八卦基本属性表 <a class="header-anchor" href="#六、八卦基本属性表" aria-label="Permalink to &quot;六、八卦基本属性表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">卦名</th><th style="text-align:center;">符号</th><th style="text-align:center;">自然象</th><th style="text-align:center;">家庭</th><th style="text-align:center;">身体</th><th style="text-align:center;">先天方位</th><th style="text-align:center;">五行</th><th style="text-align:center;">先天序数</th></tr></thead><tbody><tr><td style="text-align:center;">乾</td><td style="text-align:center;">☰</td><td style="text-align:center;">天</td><td style="text-align:center;">父</td><td style="text-align:center;">首</td><td style="text-align:center;">南</td><td style="text-align:center;">金</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">兑</td><td style="text-align:center;">☱</td><td style="text-align:center;">泽</td><td style="text-align:center;">少女</td><td style="text-align:center;">口</td><td style="text-align:center;">东南</td><td style="text-align:center;">金</td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;">离</td><td style="text-align:center;">☲</td><td style="text-align:center;">火</td><td style="text-align:center;">中女</td><td style="text-align:center;">目</td><td style="text-align:center;">东</td><td style="text-align:center;">火</td><td style="text-align:center;">3</td></tr><tr><td style="text-align:center;">震</td><td style="text-align:center;">☳</td><td style="text-align:center;">雷</td><td style="text-align:center;">长男</td><td style="text-align:center;">足</td><td style="text-align:center;">东北</td><td style="text-align:center;">木</td><td style="text-align:center;">4</td></tr><tr><td style="text-align:center;">巽</td><td style="text-align:center;">☴</td><td style="text-align:center;">风</td><td style="text-align:center;">长女</td><td style="text-align:center;">股</td><td style="text-align:center;">西南</td><td style="text-align:center;">木</td><td style="text-align:center;">5</td></tr><tr><td style="text-align:center;">坎</td><td style="text-align:center;">☵</td><td style="text-align:center;">水</td><td style="text-align:center;">中男</td><td style="text-align:center;">耳</td><td style="text-align:center;">西</td><td style="text-align:center;">水</td><td style="text-align:center;">6</td></tr><tr><td style="text-align:center;">艮</td><td style="text-align:center;">☶</td><td style="text-align:center;">山</td><td style="text-align:center;">少男</td><td style="text-align:center;">手</td><td style="text-align:center;">西北</td><td style="text-align:center;">土</td><td style="text-align:center;">7</td></tr><tr><td style="text-align:center;">坤</td><td style="text-align:center;">☷</td><td style="text-align:center;">地</td><td style="text-align:center;">母</td><td style="text-align:center;">腹</td><td style="text-align:center;">北</td><td style="text-align:center;">土</td><td style="text-align:center;">8</td></tr></tbody></table><blockquote><p>【原典依据】</p><ul><li>自然象、家庭象、身体象：《周易·说卦传》第九—十一章</li><li>先天方位与序数：邵雍《皇极经世书》（北宋），朱熹《周易本义》定型（南宋，1177年）</li></ul></blockquote><hr><h2 id="七、先天八卦的核心结构-对称" tabindex="-1">七、先天八卦的核心结构：对称 <a class="header-anchor" href="#七、先天八卦的核心结构-对称" aria-label="Permalink to &quot;七、先天八卦的核心结构：对称&quot;">​</a></h2><p>先天八卦最重要的特征，不是方位，不是五行，而是<strong>对称</strong>。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以乾坤连线为轴（南北轴）：左右完全对称。</span></span>
<span class="line"><span>以坎离连线为轴（东西轴）：上下完全对称。</span></span>
<span class="line"><span>圆形排布：任意相对两卦，阴阳爻完全互换。</span></span>
<span class="line"><span>= 整个圆，是一个完美的阴阳对称体。</span></span></code></pre></div><p><strong>这就是先天八卦的哲学核心：</strong></p><blockquote><p>宇宙在本质上是对称的。<br> 有乾必有坤，有水必有火，有山必有泽，有雷必有风。<br> 没有任何一种状态是孤立存在的，每一种存在，都有其对应的镜像。</p></blockquote><p>可以做一个验证：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>取任意一卦，把所有爻阴阳互换，得到的必然是它的对卦：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  乾 ☰（三阳）→ 互换 → 坤 ☷（三阴）✓</span></span>
<span class="line"><span>  离 ☲（中阳）→ 互换 → 坎 ☵（中阴）✓</span></span>
<span class="line"><span>  震 ☳（下阳）→ 互换 → 巽 ☴（下阴）✓</span></span>
<span class="line"><span>  兑 ☱（上阳）→ 互换 → 艮 ☶（上阴）✓</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 四对，八卦，完整闭合，无一例外。</span></span></code></pre></div><p>这不是巧合，是“象帝之先”，是道的设计。</p><h2 id="八、-数往者顺-知来者逆-——先天八卦的时间观" tabindex="-1">八、&quot;数往者顺，知来者逆&quot;——先天八卦的时间观 <a class="header-anchor" href="#八、-数往者顺-知来者逆-——先天八卦的时间观" aria-label="Permalink to &quot;八、&quot;数往者顺，知来者逆&quot;——先天八卦的时间观&quot;">​</a></h2><blockquote><p>【原典】《周易·说卦传》第三章<br> 【原文】<strong>数往者顺，知来者逆，是故易逆数也。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>顺时针 = 阳卦序列（乾→兑→离→震）= 阳气从盛到衰，&quot;数往&quot;</span></span>
<span class="line"><span>逆时针 = 阴卦序列（坤→艮→坎→巽）= 阴气从盛到衰，&quot;知来&quot;</span></span>
<span class="line"><span>两个方向同时运行，构成完整的阴阳消长循环。</span></span></code></pre></div><p>用白话说：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;数往者顺&quot;</span></span>
<span class="line"><span>= 已经发生的事，顺着时间轴往回数，是顺的，是已知的。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;知来者逆&quot;</span></span>
<span class="line"><span>= 要预知未来，必须逆着现象往回推，找到它的根。</span></span>
<span class="line"><span>  易学的逻辑，是&quot;逆推&quot;——</span></span>
<span class="line"><span>  不是从原因推结果，而是从现象推本质。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;是故易逆数也&quot;</span></span>
<span class="line"><span>= 所以《易》的思维方式，本质上是逆向思维。</span></span></code></pre></div><blockquote><p>温海明《先天学之自得，后天学之无奈》（《周易研究》，2008年）指出：<br> 邵雍先天学的核心，是建立&quot;以数推理宇宙演化&quot;的体系，&quot;数往知来&quot;是其方法论的核心命题。</p></blockquote><hr><h2 id="九、现代解读-先天八卦在说什么" tabindex="-1">九、现代解读：先天八卦在说什么？ <a class="header-anchor" href="#九、现代解读-先天八卦在说什么" aria-label="Permalink to &quot;九、现代解读：先天八卦在说什么？&quot;">​</a></h2><p><strong>第一件：建立穷举的分类系统</strong></p><blockquote><p>从太极到两仪到四象到八卦，用二分法穷举了所有基本状态。<br> 不是&quot;大概分成几类&quot;，而是逻辑上的完备分类。<br> 三爻八卦，2³=8，不多不少，恰好覆盖所有基本状态。</p></blockquote><p><strong>第二件：揭示精确的对称结构</strong></p><blockquote><p>乾（111）的镜像精确是坤（000），<br> 离（101）的镜像精确是坎（010）——<br> 每一位阴阳互换，分毫不差。<br> 这是数学意义上的精确对称，不是模糊的&quot;相对&quot;概念。</p></blockquote><p><strong>第三件：提供推演的起点工具</strong></p><blockquote><p>八卦两两相叠 = 64卦 = 64种基本情境。<br> 64卦 × 6爻 = 384种具体变化节点。<br> 先天八卦是整个推演系统的逻辑起点。</p></blockquote><hr><h2 id="十、先天与后天的接口" tabindex="-1">十、先天与后天的接口 <a class="header-anchor" href="#十、先天与后天的接口" aria-label="Permalink to &quot;十、先天与后天的接口&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先天（体）              后天（用）</span></span>
<span class="line"><span>────────────────────────────────────</span></span>
<span class="line"><span>本质关系                时空流行</span></span>
<span class="line"><span>对称结构                方位运动</span></span>
<span class="line"><span>静态                    动态</span></span>
<span class="line"><span>《说卦传》第三章        《说卦传》第五章</span></span>
<span class="line"><span>宇宙的&quot;基因图谱&quot;        宇宙的&quot;运行地图&quot;</span></span></code></pre></div><p><strong>一个关键提醒（承接上一篇河图洛书的考证结论）：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先天八卦方位（乾南·坤北·离东·坎西）</span></span>
<span class="line"><span>≠ 河图五行方位（北水·南火·东木·西金）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>河图方位 = 后天五行方位，与后天八卦一致。</span></span>
<span class="line"><span>先天八卦方位 = 乾坤定上下，坎离列左右，</span></span>
<span class="line"><span>               与五行方位不对应。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两者是不同层面的体系，不可混用。</span></span>
<span class="line"><span>（详见第04篇·河图洛书·补充说明）</span></span></code></pre></div><hr><h2 id="十一、本章小结" tabindex="-1">十一、本章小结 <a class="header-anchor" href="#十一、本章小结" aria-label="Permalink to &quot;十一、本章小结&quot;">​</a></h2><p>先天八卦，说了一件事，但这件事很大：</p><blockquote><p><strong>宇宙在本质上，是一个完美的对称结构。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 对称即完整</span></span>
<span class="line"><span>   有乾必有坤，阴阳各半，不偏不倚。</span></span>
<span class="line"><span>   宇宙不是单极的，是成对出现的。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 对立非对抗</span></span>
<span class="line"><span>   &quot;水火不相射&quot;——对立是结构性的存在方式，不是战争。</span></span>
<span class="line"><span>   坎离相对，各守其位，正因为对立，系统才稳定。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 本质先于现象</span></span>
<span class="line"><span>   先天在后天之前，体在用之前。</span></span>
<span class="line"><span>   要理解事物如何运动，必须先理解事物的本质关系。</span></span></code></pre></div><p>最后说一句实在话：</p><blockquote><p>先天八卦这张图，画的不是某个具体的东西，画的是<strong>关系本身</strong>。</p><p>它告诉你：在这个宇宙里，没有任何东西是孤立的，每一个存在，都在和它的镜像对话。</p><p>乾在南，坤在北，遥遥相对，从未相遇，却共同撑起了整个宇宙。</p><p>这，大概就是古人先辈给我们留下的最简洁的宇宙观了。</p></blockquote><hr><h2 id="附录-引用索引" tabindex="-1">附录：引用索引 <a class="header-anchor" href="#附录-引用索引" aria-label="Permalink to &quot;附录：引用索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">引用内容</th><th style="text-align:left;">原典／来源</th><th style="text-align:left;">时代／年份</th></tr></thead><tbody><tr><td style="text-align:left;">&quot;天地定位，山泽通气……&quot;</td><td style="text-align:left;">《周易·说卦传》第三章</td><td style="text-align:left;">西周至春秋</td></tr><tr><td style="text-align:left;">&quot;易有太极，是生两仪……&quot;</td><td style="text-align:left;">《周易·系辞上传》第十一章</td><td style="text-align:left;">西周至春秋</td></tr><tr><td style="text-align:left;">八卦自然象、家庭象、身体象</td><td style="text-align:left;">《周易·说卦传》第九—十一章</td><td style="text-align:left;">西周至春秋</td></tr><tr><td style="text-align:left;">&quot;数往者顺，知来者逆……&quot;</td><td style="text-align:left;">《周易·说卦传》第三章</td><td style="text-align:left;">西周至春秋</td></tr><tr><td style="text-align:left;">&quot;先天之学，心也；后天之学，迹也&quot;</td><td style="text-align:left;">邵雍《观物外篇》</td><td style="text-align:left;">北宋，约1060年代</td></tr><tr><td style="text-align:left;">先天八卦序数与方位</td><td style="text-align:left;">邵雍《皇极经世书》</td><td style="text-align:left;">北宋，1060年代</td></tr><tr><td style="text-align:left;">先天八卦图式定型</td><td style="text-align:left;">朱熹《周易本义》</td><td style="text-align:left;">南宋，1177年</td></tr><tr><td style="text-align:left;">先天学与道教丹道关系</td><td style="text-align:left;">章伟文《先天学与道教丹道之关系考察》</td><td style="text-align:left;">《周易研究》，2014年</td></tr><tr><td style="text-align:left;">邵雍&quot;数往知来&quot;方法论</td><td style="text-align:left;">温海明《先天学之自得，后天学之无奈》</td><td style="text-align:left;">《周易研究》，2008年</td></tr><tr><td style="text-align:left;">先天图式文献来源辨析</td><td style="text-align:left;">廖名春《周易经传与易学史新论》</td><td style="text-align:left;">齐鲁书社，2001年</td></tr><tr><td style="text-align:left;">陈抟与邵雍先天学渊源</td><td style="text-align:left;">盖建民、林文钦《陈抟的先天易学思想探析》</td><td style="text-align:left;">《湖南大学学报》，2016年</td></tr><tr><td style="text-align:left;">莱布尼茨与先天六十四卦</td><td style="text-align:left;">莱布尼茨致白晋信，1703年</td><td style="text-align:left;">1703年</td></tr></tbody></table><hr><p><em>文档版本：v1.0 · 先天八卦 ｜ 2026年7月 ｜ 持续更新中</em></p>`,88)])])}const h=a(l,[["render",p]]);export{u as __pageData,h as default};
